// X4a: append new raw-assumed prices; preserve 2026-09-18 department.
const input = $('전체 건수와 일봉 검증1').first().json;
const baseline = '2026-09-18';
const cols = {
 store_prices:['date','ticker','open','high','low','close','volume','value'],
 store_krx_daily:['date','ticker','name','market','dept','open_raw','high_raw','low_raw','close_raw','volume_raw','value','marketcap','shares'],
 store_marketcap:['date','ticker','marketcap','shares','market']
};
const existing = Object.fromEntries(Object.keys(cols).map(t=>[t,new Map()]));
const dept = new Map();
for(const item of $input.all()) {
 const {kind,payload}=item.json;
 const row=typeof payload==='string'?JSON.parse(payload):payload;
 if(kind==='dept') dept.set(row.ticker,row.dept);
 else if(existing[kind]) existing[kind].set(row.date+'/'+row.ticker,row);
}
const pending=Object.fromEntries(Object.keys(cols).map(t=>[t,[]]));
const report={status:'DB_COMMITTED',source:input.source,beginDate:input.beginDate,endDate:input.endDate,latestDate:input.latestDate,apiRows:input.apiRows,selectedRows:input.selectedRows,inserted:{},unchanged:{},overlap:{checked:0,rawDifferent:0,adjustedDifferent:0},missingDepartment:0,dbWritten:true,analysisAsOf:'2026-09-18',notice:'X4a 승인: 신규 날짜 원주가를 prices에 적재. dept는 2026-09-18 값 유지. 지수·마스터·웹 분석 기준일은 변경하지 않음.'};
for(const t of Object.keys(cols))report.unchanged[t]=0;
const equal=(a,b)=>a==null||b==null?a==null&&b==null:String(a)===String(b);
for(const r of input.rows){
 const d=dept.get(r.ticker)??null;
 const wanted={
  store_prices:{date:r.date,ticker:r.ticker,open:r.open_raw,high:r.high_raw,low:r.low_raw,close:r.close_raw,volume:r.volume_raw,value:r.value},
  store_krx_daily:{...r,dept:d},
  store_marketcap:r
 };
 const key=r.date+'/'+r.ticker;
 if(r.date<=baseline){
  if(r.date===baseline){
   const raw=existing.store_krx_daily.get(key),price=existing.store_prices.get(key);
   if(raw){report.overlap.checked++;if(['open_raw','high_raw','low_raw','close_raw','volume_raw','value','marketcap','shares'].some(k=>!equal(raw[k],r[k])))report.overlap.rawDifferent++;}
   if(price&&cols.store_prices.some(k=>!equal(price[k],wanted.store_prices[k])))report.overlap.adjustedDifferent++;
  }
  continue;
 }
 if(d===null)report.missingDepartment++;
 for(const [table,fields] of Object.entries(cols)){
  const prior=existing[table].get(key),row=wanted[table];
  if(prior){
   const differences=fields.filter(k=>!equal(prior[k],row[k]));
   if(differences.length)throw new Error('기존 값 충돌: '+table+' '+key+' fields='+differences.join(',')+'; 덮어쓰지 않았습니다.');
   report.unchanged[table]++;
  }else pending[table].push(Object.fromEntries(fields.map(k=>[k,row[k]])));
 }
}
// No writes to historical dates. A mismatch in the raw baseline blocks the trial.
if(report.overlap.rawDifferent)throw new Error('9/18 원주가 대조 불일치 '+report.overlap.rawDifferent+'건: 저장 전 확인 필요');
const types={date:'DATE',ticker:'VARCHAR(20)',name:'VARCHAR(48)',market:'VARCHAR(20)',dept:'VARCHAR(45)'};
const output=[];
for(const [table,rows] of Object.entries(pending)){
 report.inserted[table]=rows.length;
 const fields=cols[table];
 const sql='INSERT INTO `'+table+'` ('+fields.map(k=>'`'+k+'`').join(',')+') SELECT '+fields.map(k=>'j.`'+k+'`').join(',')+" FROM JSON_TABLE($1, '$[*]' COLUMNS ("+fields.map(k=>'`'+k+'` '+(types[k]||'BIGINT')+" PATH '$."+k+"' ERROR ON ERROR").join(',')+')) AS j';
 for(let i=0;i<rows.length;i+=500)output.push({json:{query:sql,params:[JSON.stringify(rows.slice(i,i+500))]}});
}
if(!output.length)output.push({json:{query:'SELECT 1 AS no_new_rows',params:[]}});
output[0].json.report=report;
return output;

// 날짜를 지정하면 초기 과거 자료 확인에 사용합니다. API 키를 여기에 넣지 마세요.
const config = { beginDate: '', endDate: '', lookbackDays: 7, maxRangeDays: 31, pageSize: 1000 };
const now = $now.setZone('Asia/Seoul');
function valid(s) { if (!/^\d{8}$/.test(s)) return false; const d = new Date(s.slice(0,4)+'-'+s.slice(4,6)+'-'+s.slice(6,8)+'T00:00:00Z'); return !isNaN(d) && d.toISOString().slice(0,10).replace(/-/g,'') === s; }
if (Boolean(config.beginDate) !== Boolean(config.endDate)) throw new Error('beginDate와 endDate를 함께 지정하세요.');
const endDate = config.endDate || now.minus({days:1}).toFormat('yyyyMMdd');
const beginDate = config.beginDate || now.minus({days:config.lookbackDays}).toFormat('yyyyMMdd');
if (!valid(beginDate) || !valid(endDate)) throw new Error('날짜 형식은 실제 존재하는 YYYYMMDD여야 합니다.');
const dateMs = s => Date.parse(s.slice(0,4)+'-'+s.slice(4,6)+'-'+s.slice(6,8)+'T00:00:00Z');
if (beginDate > endDate || endDate >= now.toFormat('yyyyMMdd') || (dateMs(endDate)-dateMs(beginDate))/86400000 >= config.maxRangeDays) throw new Error('조회 기간은 어제까지, 한 번에 최대 31일입니다.');
return [{json:{beginDate,endDate,pageSize:config.pageSize,requestedAt:now.toISO(),source:'FSC_STOCK_V2',dbWriteEnabled:false}}];

const config = $('조회 기간 설정1').first().json;
const pages = $input.all().map(i => i.json);
if (!pages.length) throw new Error('응답 없음: 정상 수집으로 처리하지 않습니다.');
const rows = [], seen = new Set(); let expected = null, size = null;
const fail = text => { throw new Error(text); };
const integer = (v, field, max = '9223372036854775807') => {
  if (typeof v === 'number' && !Number.isSafeInteger(v)) fail(field+': 안전하지 않은 숫자 응답');
  const s = String(v ?? '').trim();
  if (!/^\d+$/.test(s) || BigInt(s) > BigInt(max)) fail(field+': 정수 범위 오류');
  return BigInt(s).toString();
};
const validDate = s => { if (!/^\d{8}$/.test(s)) return false; const d = new Date(s.slice(0,4)+'-'+s.slice(4,6)+'-'+s.slice(6,8)+'T00:00:00Z'); return !isNaN(d) && d.toISOString().slice(0,10).replace(/-/g,'') === s; };
for (let i = 0; i < pages.length; i++) {
  const response = pages[i].response;
  if (String(response?.header?.resultCode) !== '00') fail('API 업무 오류: resultCode='+String(response?.header?.resultCode ?? 'missing')+' (키/승인/한도 확인)');
  const b = response.body;
  if (!b) fail('API body 없음');
  const count = Number(integer(b.totalCount,'totalCount','1000000'));
  const pageSize = Number(integer(b.numOfRows,'numOfRows','10000'));
  if (pageSize < 1 || Number(b.pageNo) !== i+1) fail('페이지 순서 또는 크기 오류');
  if (expected === null) { expected=count; size=pageSize; }
  if (count !== expected || pageSize !== size) fail('조회 중 페이지 총건수/크기가 변경됨: 다시 실행하세요.');
  const raw = b.items?.item;
  const list = raw == null || raw === '' ? [] : Array.isArray(raw) ? raw : [raw];
  if (list.length !== Math.max(0,Math.min(size,expected-i*size))) fail('페이지 일부가 누락되었습니다.');
  for (const r of list) {
    const day = String(r.basDt), ticker = String(r.srtnCd ?? '');
    if (!validDate(day) || day < config.beginDate || day > config.endDate) fail('조회 범위 밖이거나 잘못된 기준일');
    if (!/^[0-9A-Z]{6}$/.test(ticker)) fail('6자리 종목 코드 오류: '+ticker+' / '+r.itmsNm);
    const key = ticker+':'+day;
    if (seen.has(key)) fail('중복 키 발견: '+key);
    seen.add(key);
    if (!['KOSPI','KOSDAQ','KONEX'].includes(r.mrktCtg)) fail('알 수 없는 시장 구분');
    const fields = {};
    for (const [target,source] of Object.entries({open_raw:'mkp',high_raw:'hipr',low_raw:'lopr',close_raw:'clpr',volume_raw:'trqu',value:'trPrc',marketcap:'mrktTotAmt',shares:'lstgStCnt'})) fields[target]=integer(r[source],source);
    const o=BigInt(fields.open_raw),h=BigInt(fields.high_raw),l=BigInt(fields.low_raw),c=BigInt(fields.close_raw),v=BigInt(fields.volume_raw);
    // 거래 정지일은 O/H/L=0, 종가가 남을 수 있습니다.
    const halted = o===0n && h===0n && l===0n && v===0n;
    if (!halted && (o<=0n || c<=0n || l<=0n || h<l || h<o || h<c || l>o || l>c)) fail('OHLC 범위 오류: '+key);
    if (typeof r.itmsNm !== 'string' || !r.itmsNm.trim()) fail('종목명 누락');
    if (r.mrktCtg !== 'KONEX') rows.push({date:day.slice(0,4)+'-'+day.slice(4,6)+'-'+day.slice(6,8),ticker,name:r.itmsNm,market:r.mrktCtg,...fields,source:'FSC_STOCK_V2',price_basis:'raw_unadjusted',dept:null,halted});
  }
}
if (pages.length !== Math.max(1,Math.ceil(expected/size)) || seen.size !== expected) fail('전체 페이지 수집 미완료: DB 저장 금지');
if (!rows.length) fail('조회 결과 없음: 미게시/휴장/필터 여부 확인 필요. 수집 완료로 처리하지 않습니다.');
rows.sort((a,b)=>a.date.localeCompare(b.date)||a.ticker.localeCompare(b.ticker));
const counts = {};
for (const r of rows) { const key=r.date+'/'+r.market; counts[key]=(counts[key]||0)+1; }
const latestDate = rows[rows.length-1].date;
return [{json:{status:'VALIDATED_NOT_STORED',source:config.source,beginDate:config.beginDate,endDate:config.endDate,requestedAt:config.requestedAt,pages:pages.length,apiRows:expected,selectedRows:rows.length,latestDate,latestMatchesRequestedEnd:latestDate.replace(/-/g,'')===config.endDate,counts,dbWritten:false,missingMappings:['store_krx_daily.dept','store_prices: 수정주가 일치 검증 필요'],notice:'검증 파일 생성만 완료. DB 저장/Parquet/웹 갱신은 수행하지 않음. 최신 기준일을 확인하세요.',rows}}];
